<script setup lang="ts">
import { ref } from 'vue'
import {useUserStore} from '../../store/modules/user'
import {request} from '../../utils/request'
import {toast} from '../../utils/format'
const user=useUserStore(), username=ref(''),password=ref(''),name=ref(''),phone=ref(''),register=ref(false),busy=ref(false), agreed=ref(false),role=ref('OWNER')
function browse(){uni.reLaunch({url:'/pages/index/index'})}
async function submit(){if(!agreed.value)return toast('请先阅读并同意服务与隐私说明');if(busy.value)return;busy.value=true;try{if(register.value)await request('/auth/register','POST',{username:username.value,password:password.value,name:name.value,phone:phone.value});await user.login(username.value,password.value);uni.reLaunch({url:'/pages/'+(user.sitter?'sitter/tasks':role.value==='SITTER'?'sitter/apply':'index/index')})}catch(e:any){toast(e.message)}finally{busy.value=false}}
</script>
<template><view class="shell login-shell"><view style="padding:30px 0"><view class="avatar" style="width:76px;height:76px;font-size:40px;margin-bottom:24px">🐾</view><view class="title">你不在家，<br/>爱也不缺席。</view><view class="subtitle">专业上门喂养，认真照顾每一份牵挂。</view></view><view class="tabs"><view :class="['tab',{active:role==='OWNER'}]" @click="role='OWNER'">我是宠主</view><view :class="['tab',{active:role==='SITTER'}]" @click="role='SITTER'">我是喂养师</view></view><view class="card"><view class="section" style="margin-top:0">{{register?'创建暖爪账号':'欢迎回来'}}</view><text class="label">账号</text><view class="field"><input v-model="username" placeholder="请输入账号" maxlength="32"/></view><text class="label">密码</text><view class="field"><input v-model="password" password placeholder="请输入密码（至少 8 位）" maxlength="64"/></view><template v-if="register"><text class="label">姓名</text><view class="field"><input v-model="name" placeholder="怎么称呼您"/></view><text class="label">手机号码</text><view class="field"><input v-model="phone" type="number" maxlength="11" placeholder="请输入手机号"/></view></template><view class="row-start muted" style="margin-bottom:18px" @click="agreed=!agreed"><text class="checkbox">{{agreed?'✓':''}}</text><text>同意仅为预约、履约与客服联系使用本次填写的信息；不在公开页面展示家庭地址。</text></view><button class="primary" :loading="busy" :disabled="busy" @click="submit">{{register?'注册并继续':'登录'}}</button><view style="text-align:center;margin-top:16px" class="link" @click="register=!register">{{register?'已有账号？去登录':'还没有账号？立即注册'}}</view><view style="text-align:center;margin-top:16px" class="link" @click="browse">先逛逛</view></view><view class="footer-note">账号权限以平台审核结果为准<br/>喂养师新账号注册后可提交入驻申请</view></view></template>
<style>.login-shell{padding-top:80px}</style>
